{
  "description": "The creature is shown in right-facing side profile standing on a small patch of rocky ground against a plain light background. It has the overall body shape, proportions and posture of a stocky horse, with dense shaggy brown fur covering the head, neck, lower chest, all four legs and the tail, but the entire torso, sides and belly from just behind the shoulders to just in front of the hindquarters is covered in a contrasting pale, mottled, bumpy skin with irregular dark greenish-brown blotches and numerous small raised whitish nodules. The fur meets this scaly skin along abrupt, slightly ruffled and overlapping edges at the base of the neck, around the chest, along the belly and around the upper thighs, giving the midsection a distinct textured covering unlike the surrounding hair.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated horse-like head at the front right of the body, covered in short brown fur with a darker muzzle, large dark nostril, small closed mouth with visible lips and whiskers, and a dark brown eye with a catchlight; viewed in three-quarter profile facing right",
      "where": "at the front end of the neck, far right of the image"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular ears with brown fur and darker interiors, with visible inner hair",
      "where": "on top of the head, one slightly behind the other"
    },
    {
      "part": "mane",
      "looks_like": "short, thick, shaggy, dark brown mane of coarse hair standing along the dorsal midline",
      "where": "running along the top of the neck from just behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, straight, brown-furred legs with visible knee and hock joints and shaggy hair along the lower segments",
      "where": "two forelegs under the chest at the right-center and two hind legs under the rear at the left-center, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four solid, rounded, dark brown hooves with visible hoof wall and sole, slightly worn",
      "where": "at the bottom tip of each leg, in contact with the rocky ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, straight tail made of long coarse brown hair hanging vertically with strands reaching near the hocks",
      "where": "attached at the rear of the body, far left of the image, hanging down behind the hind legs"
    },
    {
      "part": "scales",
      "looks_like": "mottled, bumpy, scaly-textured skin covering the torso, with a pale off-white belly fading to grey-green and brown dorsally, covered in many small raised white bumps and larger dark blotches, with a slightly wrinkled surface and a distinct ruffled rim where it meets the fur",
      "where": "covering the entire midsection of the body from behind the forelegs to in front of the hind legs, wrapping around the sides, back and belly, with edges at the neck, chest, belly and thighs"
    },
    {
      "part": "markings",
      "looks_like": "irregular dark brown and grey-green spots and blotches interspersed with numerous small round whitish nodules scattered densely over the scaly midsection",
      "where": "distributed across the scaly skin on the back, sides and belly"
    }
  ],
  "attached_objects": [],
  "animals": [
    "horse",
    "fish"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
